-- For God so loved the world, that He gave His only begotten Son,
-- that all who believe in Him should not perish but have everlasting life.
-- — John 3:16

-- 1JOHN - POR Combined
-- Generated: 2026-01-22T06:35:51.929Z

-- c005-v001: Todo o que–crê que Jesus é o Cristo, de — Deus é–nascido, e todo o que–ama o que–gerou, ama <também> o gerado dele —.
-- c005-v002: Nisto — conhecemos que amamos os filhos de Deus, quando — Deus amamos, e os mandamentos dele praticamos.
-- c005-v003: Este pois é o amor de Deus, que os mandamentos dele guardemos; e os mandamentos dele pesados não são.
-- c005-v004: Porque todo o nascido de — Deus, vence o mundo; e esta é a vitória a que–venceu o mundo— a fé nossa.
-- c005-v005: Quem <porém> é o que–vence o mundo, senão — o que–crê que Jesus é o Filho de Deus?
-- c005-v006: Este é o que–veio por água e sangue, Jesus Cristo; não pela — água somente, mas pela — água e pelo — sangue. E o Espírito é o que–testifica, porque o Espírito é a verdade.
-- c005-v007: Porque três são os que–testificam {no — céu: o Pai, o Verbo, e o Santo Espírito— e estes os três, um são}:
-- c005-v008: o Espírito, e a água, e o sangue— e os três para o um são.
-- c005-v009: Se o testemunho dos homens recebemos, o testemunho de Deus maior é. Porque este é o testemunho de Deus, que testemunhou acerca do Filho dele.
-- c005-v010: O que–crê no — Filho de Deus, tem o testemunho em si–mesmo; o não que–crê em Deus, mentiroso o–fez ele, porque não creu no — testemunho que testemunhou — Deus, acerca do Filho dele.
-- c005-v011: E este é o testemunho, que vida eterna deu «— Deus», a–nós e esta a vida no — Filho dele está.
-- c005-v012: O que–tem o Filho, tem a vida: o não que–tem o Filho de Deus, a vida não tem.
-- c005-v013: Estas–coisas escrevi a–vós para–que saibais que vida tendes eterna, aos que–creem no — nome do Filho de Deus, <e para–que creiais no — nome do Filho de Deus>.
-- c005-v014: E esta é a confiança que temos para–com ele, que se alguma–coisa pedirmos segundo a vontade dele, ouve a–nós.
-- c005-v015: E se sabemos que nos–ouve a–nós, o–que — pedirmos, sabemos que temos os pedidos que pedimos da–parte dele.
-- c005-v016: Se alguém vir o irmão dele pecando pecado não para morte, pedirá, e dará a–ele vida— aos que–pecam não para morte. Há pecado para morte; não acerca daquele digo que ore.
-- c005-v017: Toda injustiça pecado é; e há pecado não para morte.
-- c005-v018: Sabemos que todo o nascido de — Deus não peca, mas o gerado de — Deus o–guarda, ele, e o maligno não o–toca dele.
-- c005-v019: Sabemos que de — Deus somos, e o mundo inteiro, no — maligno jaz.
-- c005-v020: E–sabemos porém que o Filho de Deus veio, e nos–deu a–nós entendimento, para–que conheçamos o verdadeiro; e estamos no — verdadeiro, no — Filho dele, Jesus Cristo. Este é o verdadeiro Deus, e vida eterna.
-- c005-v021: Filhinhos, guardai–vos a–vós–mesmos dos — ídolos. <Amém>

